function getWengineStat(wKey) {
  return allStats.wengine[wKey];
}
function getWengineParams(wk) {
  const { phase: phase96 } = getWengineStat(wk);
  return transposeArray(phase96.map((singlePhase) => singlePhase.params)).map(
    (params) => [-1, ...params]
  );
}

